import{z as o,x as n,o as A,c as d,q as t,j as s,D as B,d as a,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"安全边界","description":"","frontmatter":{"title":"安全边界","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virt-security-boundary.md","filePath":"cs/virt-security-boundary.md","lastUpdated":1791413859000}'),c={name:"cs/virt-security-boundary.md"};function p(h,E,D,m,C,u){const r=n("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="安全边界" tabindex="-1">安全边界 <a class="header-anchor" href="#安全边界" aria-label="Permalink to &quot;安全边界&quot;">​</a></h1><div class="epigraph"><p>隔离强度等于你必须信任的那份代码的正确性。比较两种隔离，别比标签，比三件事：多少行代码、暴露多少接口、补丁窗口多长。</p><footer>—— 据 Barham et al., Xen, SOSP 2003 的隔离目标与各机制公开文档整理</footer></div><p><a href="/cs/virt-gpu">上一课</a>看到共享粒度与信任面同向增长：MIG 用硬件隔离客户，MPS 则让一个进程崩掉全组。本课把这条直觉推广成整门课程的度量衡：每条「隔离」主张背后是一份 <strong>TCB</strong>——为了让隔离成立，你必须假设正确的全部代码与配置。主干课的<a href="/cs/vm-escape">虚拟机逃逸</a>与<a href="/cs/container-escape">容器逃逸</a>分别点过两面；本课把光谱排成一架梯子，给每一级标上尺寸。</p><p><span class="marginnote">TCB 可翻译成「信任清单」：为了让「容器出不来」这句话成立，你必须假设正确运行的全部东西——宿主内核、运行时二进制、你写进 JSON 的每一条配置。清单越长，隔离成立的赌注就越大；比较两种隔离，本质是在比谁的清单短、谁的清单每行更可靠。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>从下往上数。容器：共享内核意味着 TCB 是<strong>整个宿主内核</strong>——以千万行计的代码、每天在长的攻击面，外加运行时与你写进 JSON 的配置；内核一个 0-day，容器与宿主同沉浮，这是共享内核路线的地板而不是配置失误。加固件（<a href="/cs/seccomp-filter">seccomp 过滤</a>、<a href="/cs/linux-capabilities">capabilities 裁剪</a>、LSM）不换边界，只缩暴露面：拦掉一百个系统调用里没人用的九十个，攻击面小一个量级，内核该有洞还是有洞。gVisor：TCB 换成 Sentry 这个用户态内核加上「宿主只暴露的少量调用」，内核洞仍在，但应用要碰到它得先穿过 Sentry 的重新实现。微虚机与完整虚机：TCB 是 VMM 的设备模型加 <a href="/cs/kvm-qemu">KVM</a>——第一课说过，陷入路径由硬件接住后，设备模拟重新把信任面拉大；Firecracker 用砍设备把这份账压小，Kata 把它接到 OCI 契约上。梯子顶端是形式化微内核：<a href="/cs/microkernel-sel4">seL4</a> 的核心以万行计，且有机器检查的证明——不是无洞，是「洞在哪」被数学管住。</p><p><span class="marginnote">数字实例：Linux 内核以千万行计，gVisor 的 Sentry 以十万行计，seL4 的核心以万行计且带机器检查的证明——梯子每上一级，你要信任的代码约少一个量级；行数不是安全的证明，但它标出了「需要被证明的东西有多少」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把梯子读成账本：每一级记下必须正确的代码、暴露的接口与补丁节奏，配置单独记一本。</p><h3 id="配置是边界的另一半" tabindex="-1">配置是边界的另一半 <a class="header-anchor" href="#配置是边界的另一半" aria-label="Permalink to &quot;配置是边界的另一半&quot;">​</a></h3><p>同一机制在不同配置下隔着量级：<code>--privileged</code> 容器的 TCB 等于宿主全权；把宿主运行时套接字挂进容器等于把管理面递进去。逃逸史里这类「零漏洞越狱」占的席位不比内核 CVE 少。度量边界因此是三元积：代码量 × 暴露面 × 配置纪律，缺一项，另两项的投入就漏光。</p>',11)),(A(),s(l,null,{default:B(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%B9%E5%99%A8%3A%20%E6%95%B4%E4%B8%AA%E5%AE%BF%E4%B8%BB%E5%86%85%E6%A0%B8%22%5D%20--%3E%20H%5B%22%E5%8A%A0%E5%9B%BA%3A%20seccomp%20%E8%A3%81%E9%9D%A2%22%5D%0A%20%20H%20--%3E%20G%5B%22gVisor%3A%20%E7%94%A8%E6%88%B7%E6%80%81%E5%86%85%E6%A0%B8%E6%88%AA%E8%B0%83%E7%94%A8%22%5D%0A%20%20G%20--%3E%20M%5B%22%E5%BE%AE%E8%99%9A%E6%9C%BA%3A%20VMM%20%E8%AE%BE%E5%A4%87%E6%A8%A1%E5%9E%8B%20%2B%20KVM%22%5D%0A%20%20M%20--%3E%20F%5B%22%E5%BD%A2%E5%BC%8F%E5%8C%96%E5%BE%AE%E5%86%85%E6%A0%B8%3A%20%E4%B8%87%E8%A1%8C%E7%BA%A7%E6%9C%89%E8%AF%81%E6%98%8E%22%5D%0A%20%20DMMA%5B%22IOMMU%3A%20%E8%AE%BE%E5%A4%87%20DMA%20%E7%9A%84%E5%A2%99%22%5D%20--%3E%20M%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("两堵容易被忘掉的墙。第一堵是 DMA：直通设备（上一课的 VFIO 路线）若没有 IOMMU 把每台设备的地址翻译钉在自己的资源上，客户配一次 DMA 就能读写宿主任意物理内存——隔离在设备侧破产，与 CPU 侧做得多干净无关。第二堵在边界之下：瞬态执行漏洞（"),e("a",{href:"/cs/flush-reload"},"Flush+Reload"),a(" 一类侧信道）不从边界上翻墙，而是从墙根渗过去——同一物理核上的两个租户共享分支预测与缓存状态，「互相看不见」在微架构层是假的。这意味着隔离决策必须连同"),e("strong",null,"调度与放置"),a("一起做：高敏感负载不与不可信负载共核，边界设计再好也补不了放置错误。")],-1)),(A(),s(l,null,{default:B(()=>[i(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISO%5B%22CPU%20%E4%BE%A7%E9%9A%94%E7%A6%BB%E5%81%9A%E5%AF%B9%E4%BA%86%22%5D%20--%3E%20DMAW%7B%22DMA%20%E8%BF%99%E5%A0%B5%E5%A2%99%E8%A3%85%E4%BA%86%E5%90%97%22%7D%0A%20%20DMAW%20--%3E%7C%22%E6%97%A0%20IOMMU%22%7C%20BROKEN%5B%22%E4%B8%80%E6%AC%A1%20DMA%20%E5%8F%AF%E8%AF%BB%E5%86%99%E5%AE%BF%E4%B8%BB%E4%BB%BB%E6%84%8F%E7%89%A9%E7%90%86%E5%86%85%E5%AD%98%22%5D%0A%20%20DMAW%20--%3E%7C%22%E6%9C%89%20IOMMU%22%7C%20OK%5B%22%E8%AE%BE%E5%A4%87%E5%8F%AA%E7%A2%B0%E5%88%86%E9%85%8D%E7%BB%99%E5%AE%83%E7%9A%84%E8%B5%84%E6%BA%90%22%5D%0A%20%20ISO%20--%3E%20SIDE%7B%22%E6%A0%B8%E9%97%B4%E6%80%8E%E4%B9%88%E6%94%BE%E7%BD%AE%22%7D%0A%20%20SIDE%20--%3E%7C%22%E4%B8%8E%E4%B8%8D%E5%8F%AF%E4%BF%A1%E8%B4%9F%E8%BD%BD%E5%85%B1%E6%A0%B8%22%7C%20LEAK%5B%22%E4%BE%A7%E4%BF%A1%E9%81%93%E4%BB%8E%E5%A2%99%E6%A0%B9%E6%B8%97%E5%87%BA%22%5D%0A%20%20SIDE%20--%3E%7C%22%E9%AB%98%E6%95%8F%E6%84%9F%E4%B8%8D%E5%85%B1%E6%A0%B8%22%7C%20OK2%5B%22%E5%BE%AE%E6%9E%B6%E6%9E%84%E6%B3%84%E6%BC%8F%E9%9D%A2%E7%BC%A9%E5%B0%8F%22%5D%0A%20%20OK%20--%3E%20PLACE%5B%22%E8%BE%B9%E7%95%8C%E4%B8%8E%E6%94%BE%E7%BD%AE%E5%BF%85%E9%A1%BB%E4%B8%80%E8%B5%B7%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20OK2%20--%3E%20PLACE%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">直觉类比：侧信道不翻墙，它听墙根——同一物理核上的两个租户像合住一套隔音差的公寓，你看不见室友，却听得见他开水龙头、闻得出他做了什么饭；分支预测与缓存状态就是那堵薄墙，防御手段是「别和不可信的人分同一套公寓」。</span></p><p><span class="marginnote">误读重灾区：「VM 一定比容器安全」。VM 的 TCB 小是指核心陷入路径；QEMU 的设备模型常年是逃逸 CVE 的产地，暴露面随启用的虚拟设备数线性增长。对比必须在「同等启用特性」下做，否则比的是配置不是机制。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给逃逸步骤，不评机密计算（防运营商看内存与防租户互打是两个威胁，主干课已分开）； 多租户声学的量化归下一课之外的实验课，本课只给梯子与判据。侧信道只承认机制存在，泄漏的工程细节归安全栏的主干课。还有一个诚实的边界：TCB 尺寸可以数行数，正确性不能——百万行「没出过事」与万行「有证明」不是同一类主张，混着比会得出错的安全感。选择最终落回负载：互信的自家服务共享内核换密度，不可信代码进微虚机或更上，敏感与不可信不共核。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>边界的度量是 TCB：代码量、暴露面、配置纪律三元，缺一则漏。</li><li>梯子从下到上：共享内核容器、加固缩面、用户态内核、微虚机/虚机、形式化微内核。</li><li>加固件缩暴露面不换边界；IOMMU 是设备 DMA 那一侧的墙。</li><li>瞬态执行从墙根渗透：隔离决策必须连同核间放置一起做。</li><li>出处：Barham et al., Xen, 2003；据各机制公开文档与逃逸史整理。</li></ul>',6))])}const _=o(c,[["render",p]]);export{f as __pageData,_ as default};
